def make_shift(k):
    out=[r[:] for r in inp]
    for r in range(3,8):
        for c in range(16):
            if inp[r][c]!=8:
                out[r][c]=8
                out[r][c+k]={6:7,7:6}[inp[r][c]]
    for r in range(8,13):
        for c in range(16):
            if inp[r][c]!=8: out[r][c]={6:7,7:6}[inp[r][c]]
    return out
print(json.dumps({'action':'submit','grid':make_shift(6)}))
